print("Analyzing the pattern of optimal guesses...")

# First, let me get all optimal guesses
all_guesses = []
for g1 in range(31):
    for g2 in range(g1, 31):
        for g3 in range(g2, 31):
            all_guesses.append((g1, g2, g3))

valid_distributions = []
for x in range(31):
    for y in range(x, 31):
        for z in range(y, 31):
            if x + y + z == 30:
                valid_distributions.append((x, y, z))

# Precompute permutations
dist_permutations = {}
for dist in valid_distributions:
    x, y, z = dist
    dist_permutations[dist] = list(itertools.permutations([x, y, z]))

# Find optimal guaranteed coins
best_guaranteed_coins = -1
best_guesses = []

for guess in all_guesses:
    min_coins_for_guess = float('inf')

    for dist in valid_distributions:
        min_for_dist = float('inf')
        for perm in dist_permutations[dist]:
            total = 0
            for i in range(3):
                if guess[i] <= perm[i]:
                    total += guess[i]
            min_for_dist = min(min_for_dist, total)

        min_coins_for_guess = min(min_coins_for_guess, min_for_dist)
        if min_coins_for_guess <= best_guaranteed_coins:
            break

    if min_coins_for_guess > best_guaranteed_coins:
        best_guaranteed_coins = min_coins_for_guess
        best_guesses = [guess]
    elif min_coins_for_guess == best_guaranteed_coins:
        best_guesses.append(guess)

print(f"Optimal guaranteed coins: {best_guaranteed_coins}")
print(f"Number of optimal guesses: {len(best_guesses)}")

# Let me categorize the optimal guesses
print("\nCategorizing optimal guesses:")

# Sort guesses for analysis
best_guesses_sorted = sorted(best_guesses)

# Count by pattern
pattern_counts = {}
for guess in best_guesses_sorted:
    g1, g2, g3 = guess
    if g1 == g2 == g3:
        pattern = f"({g1}, {g2}, {g3}) - all equal"
    elif g1 == g2:
        pattern = f"({g1}, {g2}, {g3}) - first two equal"
    elif g2 == g3:
        pattern = f"({g1}, {g2}, {g3}) - last two equal"
    else:
        pattern = f"({g1}, {g2}, {g3}) - all different"

    pattern_counts[pattern] = pattern_counts.get(pattern, 0) + 1

print("\nPattern analysis:")
for pattern, count in sorted(pattern_counts.items()):
    print(f"  {pattern}: {count} guesses")

# Show first few of each pattern
print("\nExamples of optimal guesses:")
print("All equal guesses:")
equal_guesses = [g for g in best_guesses_sorted if g[0] == g[1] == g[2]]
print(f"  {equal_guesses[:5]}")

print("\nGuesses with first two equal:")
first_two_equal = [g for g in best_guesses_sorted if g[0] == g[1] and g[1] != g[2]]
print(f"  {first_two_equal[:5]}")

print("\nGuesses with last two equal:")
last_two_equal = [g for g in best_guesses_sorted if g[1] == g[2] and g[0] != g[1]]
print(f"  {last_two_equal[:5]}")

print("\nGuesses with all different:")
all_different = [g for g in best_guesses_sorted if g[0] != g[1] and g[1] != g[2]]
print(f"  {all_different[:5]}")

# Let me check if there's a pattern with the sum
print("\nChecking sum of guesses:")
for guess in best_guesses_sorted[:10]:
    print(f"  {guess}: sum = {sum(guess)}")

# Let me verify the worst-case distribution for some optimal guesses
print("\n\nVerifying worst-case for different types of optimal guesses:")

test_guesses = [(10, 10, 10), (10, 10, 15), (10, 15, 15), (5, 10, 15)]

for guess in test_guesses:
    print(f"\nFor guess {guess}:")
    worst_value = float('inf')
    worst_dists = []

    for dist in valid_distributions:
        min_for_dist = float('inf')
        for perm in dist_permutations[dist]:
            total = 0
            for i in range(3):
                if guess[i] <= perm[i]:
                    total += guess[i]
            min_for_dist = min(min_for_dist, total)

        if min_for_dist < worst_value:
            worst_value = min_for_dist
            worst_dists = [dist]
        elif min_for_dist == worst_value:
            worst_dists.append(dist)

    print(f"  Guaranteed coins: {worst_value}")
    print(f"  Example worst distributions: {worst_dists[:3]}...")"}

