{"code": "import itertools

# Function to check if a distribution is valid
def is_valid_distribution(x, y, z):
    # Nonnegative integers summing to 30
    if x + y + z != 30:
        return False

    # At least one ≥ 2
    if x < 2 and y < 2 and z < 2:
        return False

    # There exist i,j such that x_i = x_j + 6
    # Check all pairs
    numbers = [x, y, z]
    for i in range(3):
        for j in range(3):
            if i != j and numbers[i] == numbers[j] + 6:
                return True
    return False

# Generate all valid distributions
valid_distributions = []
for x in range(0, 31):
    for y in range(0, 31 - x):
        z = 30 - x - y
        if is_valid_distribution(x, y, z):
            valid_distributions.append((x, y, z))

print(f"Total valid distributions: {len(valid_distributions)}")
print("\nFirst 10 valid distributions:")
for i in range(min(10, len(valid_distributions))):
    print(f"  {valid_distributions[i]}")"}

